using ModelContextProtocol.Server;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddMcpServer()
    .WithHttpTransport()
    .WithTools<MyTools>()
    .WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

// ── Tools ──────────────────────────────────────────────────────────────

[McpServerToolType]
public class MyTools
{
    [McpServerTool(Name = "echo"), Description("Echoes the input message back.")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool(Name = "add"), Description("Adds two numbers.")]
    public static string Add(double a, double b) => $"Result: {a + b}";
}

// ── Resources ──────────────────────────────────────────────────────────

[McpServerResourceType]
public class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app_settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration.")]
    public static string GetAppSettings() =>
        """
        {
          "appName": "McpHttpServer",
          "version": "1.0.0",
          "maxConnections": 100,
          "features": {
            "logging": true,
            "metrics": true
          }
        }
        """;

    [McpServerResource(UriTemplate = "config://app/environment", Name = "environment",
        MimeType = "text/plain"),
     Description("Returns the current environment name.")]
    public static string GetEnvironment() =>
        Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production";
}
